update content_bodies set title = '【吉備津神社】～空旅時間～ 岡山市を感じるスカイウォーク', description = '岡山市のあの有名な名所や実は知らなかったあのスポット。
 空から旅してみませんか？ 

吉備津神社は、大吉備津彦大神（おおきびつひこのおおかみ）を主祭神とする大社で、本殿及び拝殿は、「比翼入母屋造」という全国唯一の造りで、国宝に指定されています。また、御本殿から南の本宮社をつなぐ約400ｍ続く廻廊（県指定文化財）や随神をお祀りする南・北随神門や御竈殿、木造獅子・狛犬は、国の重要文化財に指定されています。 

