update content_bodies set title = '花粉も邪気も吹き飛ばすー【“秘境の村”北山村へ】', description = '三重と奈良にすっぽりと囲まれ、和歌山県内の他市町村と接していない日本で唯一の“飛び地”の村、和歌山県北山村。人口約380人、面積の93％が山と森に抱かれた自然の中で、ここにしかない暮らしが静かに息づいています。幻の柑橘「じゃばら」や、全国で唯一の「観光筏下り」など、土地の恵みを活かした文化が根付く、誇り高い秘境を訪ねてみませんか。
 
＃和歌山＃北山村＃秘境の村＃飛び地＃じゃばら＃花粉症対策＃観光筏下り
 
▼花粉症も邪気も吹き飛ばす“秘境”北山村へ。ー“日本唯一”が３つもある山あいの小さな村ーの記事は下記を参照
https://www.wakayama-kanko.or.jp/features/detail_354.html' where id = '1BjWRH3k3Wqu3CzGdH1Dm';
update content_bodies set title = 'Blowing Away Pollen and Evil Spirits - [To the ''Secret Village'' of Kitayama Village]', description = 'Nestled entirely between Mie and Nara, Kitayama Village in Wakayama Prefecture is the only ''exclave'' in Japan that does not border any other cities or towns in the prefecture. With a population of about 380 and 93% of its area embraced by mountains and forests, a unique way of life quietly thrives here. Would you like to visit this proud secret place, where a culture rooted in the blessings of the land, such as the elusive citrus ''Jabara'' and the only ''tourist rafting'' in the country, flourishes?

#Wakayama #KitayamaVillage #SecretVillage #Exclave #Jabara #PollenAllergyCountermeasures #TouristRafting

▼ For the article ''To the “Secret” Kitayama Village that Blows Away Pollen and Evil Spirits - A Small Village in the Mountains with Three “Onlys” in Japan'', please refer to the link below
https://www.wakayama-kanko.or.jp/features/detail_354.html' where id = 'HQKJKPA20TkixnbnsnHar';
update content_bodies set title = '熊野御幸の足跡をたどる旅 ―祈りの道「熊野古道」をゆく―【熊野御幸ゆかりの御朱印めぐり】', description = '熊野古道とは、京都をはじめ各地から熊野三山（熊野本宮大社、熊野速玉大社、熊野那智大社・那智山青岸渡寺）へと続く参詣道で、そのうち中辺路や大辺路の一部などが「紀伊山地の霊場と参詣道」として世界遺産に登録されています。
熊野古道は、古くから人々の祈りを運び、再生の地へと導いた“よみがえりの道”。都から高貴な方々が熊野を目指して旅をした「熊野御幸（くまのごこう）」こそが、この道のはじまりなんです！
 
上皇や法皇が都・京都から大阪を経て、熊野三山（熊野本宮大社、熊野速玉大社、熊野那智大社・那智山青岸渡寺）を目指した壮大な巡礼の旅。
日本における観光のはじまりと言われる熊野御幸について紹介いたします。
 
＃和歌山＃熊野古道＃熊野御幸＃城南宮＃熊野本宮大社＃熊野速玉大社＃熊野那智大社・那智山青岸渡寺＃熊野三山＃熊野詣
 
▼熊野御幸の足跡をたどる旅 ―祈りの道「熊野古道」をゆく―の記事は下記を参照
https://www.wakayama-kanko.or.jp/features/detail_337.html' where id = '9XIzQSrH9zTFJeG8Wr8O7';
update content_bodies set title = 'A Journey Following the Footsteps of Kumano Gokō - Walking the Sacred Path ''Kumano Kodo'' - [Pilgrimage to the Sacred Seals Related to Kumano Gokō]', description = 'The Kumano Kodo is a pilgrimage route that connects various places, including Kyoto, to the three Kumano mountains (Kumano Hongu Taisha, Kumano Hayatama Taisha, Kumano Nachi Taisha and Nachi San Seiganto-ji). Parts of the Nakahechi and Ohechi routes are registered as a World Heritage site under ''Sacred Sites and Pilgrimage Routes in the Kii Mountain Range.''
The Kumano Kodo has long carried the prayers of people and led them to a place of rebirth, known as the ''Path of Resurrection.'' The ''Kumano Gokō,'' where noble individuals from the capital traveled towards Kumano, is the origin of this path!

A grand pilgrimage journey undertaken by emperors and priests from the capital, Kyoto, through Osaka, aiming for the three Kumano mountains (Kumano Hongu Taisha, Kumano Hayatama Taisha, Kumano Nachi Taisha and Nachi San Seiganto-ji).
We will introduce the Kumano Gokō, said to be the beginning of tourism in Japan.

#Wakayama #KumanoKodo #KumanoGokō #Jonangu #KumanoHonguTaisha #KumanoHayatamaTaisha #KumanoNachiTaisha #NachiSanSeigantoji #ThreeKumanoMountains #KumanoPilgrimage

▼ For the article on the journey following the footsteps of Kumano Gokō - Walking the Sacred Path ''Kumano Kodo'', please refer to the link below:
https://www.wakayama-kanko.or.jp/features/detail_337.html' where id = 'jJhcqDCQuG9Hmh89Oha0D';
