update content_bodies set title = '名古屋発！「Re: 和歌山・熊野の”とっておき”に出逢う。」', description = '名古屋発、熊野の旅へ。
世界遺産・熊野三山や熊野古道、そして温泉・絶景・グルメ・アクティビティ…たくさんの魅力が詰まった熊野を旅すれば、きっとあなたの”とっておき”が見つかるはず。


＊＊＊＊＊
出演者プロフィール【まんまるこまち】 
「食べて・飲んで」をテーマにした動画で知られる愛知県出身の人気YouTuber。特に料理とお酒を豪快に楽しむ姿が多くの女性ファンに支持されています。明るく飾らない性格が魅力で、「友達と一緒にいる気分」になる動画を配信し続けています。' where id = 'tGFYFTCNEMFvqeFGX1gQD';
update content_bodies set title = 'From Nagoya! ''Encountering the ''Best of'' Wakayama and Kumano.''', description = 'Departing from Nagoya, a journey to Kumano.
With World Heritage sites like the Kumano Sanzan, the Kumano Kodo, and attractions such as hot springs, breathtaking views, gourmet food, and activities... traveling through Kumano, filled with countless charms, is sure to help you find your ''best of''.

＊＊＊＊＊
Profile of the Performer [Manmaru Komachi]
A popular YouTuber from Aichi Prefecture known for videos themed around ''eating and drinking''. Her lively enjoyment of cooking and alcohol has garnered support from many female fans. Her bright and unpretentious personality is appealing, and she continues to deliver videos that make viewers feel like they are ''hanging out with friends''.' where id = 'BWcMqquKiBh65OJZvi1My';
