update content_bodies set title = '【一生に一度は行きたい和歌山の絶景7選】串本・古座川エリア', description = '和歌山県は海・山・川など自然の宝庫で、様々な絶景スポットがあります。
今回はそんな和歌山県の中でも、特にビューポイントが豊富な本州最南端の地「串本」と
清流の町「古座川」の絶景を紹介します。訪れたい場所があったら是非いいね！とコメントをお願いします♪
ほかにも皆さまが和歌山の観光スポットについて紹介して欲しいスポットや、聞いてみたい質問がありましたらコメントでもぜひ教えて下さい！

＜目次＞
00:00　オープニング
00:28　紹介するのは本州最南端の地「串本」と清流の町「古座川」の絶景
00:48　「橋杭岩（はしぐいいわ）」国の天然記念物にも指定される和歌山を代表する景勝地
02:22　「樫野崎（かしのざき）」断崖に建てられた灯台と海が美しい
03:16　「海金剛（うみこんごう）」鋭い奇岩が海岸にそそり立つ絶景
03:59　「くしもと大橋」串本（本土）と沖合に浮かぶ紀伊大島をつなぐビッグブリッジ
