update content_bodies set title = '【クエ】日本屈指の高級魚“和歌山で食える”超豪華フルコース', description = '幻の高級魚と呼ばれる「クエ」。古くからクエ漁が盛んな和歌山県では本場のクエ料理を堪能することができます。
ぷりぷりの食感と皮と身の間のコラーゲンや濃厚な旨味の白身が絶品なクエ料理。
漁獲量が少ない貴重なクエを和歌山県では天然・養殖ともに提供していて通年クエを楽しめます。
様々なクエ料理を紹介するので気になった方はぜひ和歌山県を訪れてクエを食べてみてください♪

