update content_bodies set title = 'Wakayama Koyasan', description = 'Now is the time to visit the powerful World Heritage Site, Koyasan.

The year 2023 marks the 1250th anniversary of the birth of Kobo Daishi Kukai, who opened Koyasan. There is increasing attention on power spot travel, with special openings of the usually closed main deity and limited edition goshuin stamps.

Let’s head to Koyasan, where the history of leisure is woven!' where id = 'qWpQEPPz1dGHVGs5leL5m';
update content_bodies set title = '「wakayama shirahama」', description = '和歌山で”海外リゾートステイ”気分が味わえる！？
パノラマに広がる水平線を眺めながら海沿いサイクリング、無人島でラグジュアリーなグランピングやBBQ...
