update content_bodies set title = 'Wakayama Shirahama', description = 'Experience the feeling of an ''overseas resort stay'' in Wakayama!?
Enjoy seaside cycling while gazing at the panoramic horizon, luxurious glamping and BBQ on a deserted island...
You can have such an overseas resort stay in Shirahama, Wakayama!' where id = 'feOiiIpOl778LPdJ3a915';
update content_bodies set title = '「wakayama nachikatsuura」', description = '「人生で一度は行きたい」聖地・和歌山県熊野エリア。
今こそ行っておきたい”パワースポット”なんです。
熊野古道の神聖な空気を浴び、幻の”もち鮪”を堪能し、太平洋を望む絶景露天風呂に癒される、極上のネイチャリング体験をチェック！
”紀伊山地の霊場と参詣道”は、世界文化遺産に登録され、2024年で20周年を迎えます。' where id = '1IqPvUP1t-SiwlpnZt4lt';
update content_bodies set title = 'Wakayama Nachikatsuura', description = 'A sacred place in the Kumano area of Wakayama Prefecture that you must visit at least once in your life.
Now is the time to experience this ''power spot''.
Bathe in the sacred air of the Kumano Kodo, savor the elusive ''mochi tuna'', and enjoy a healing experience in an open-air bath with a breathtaking view of the Pacific Ocean. Check out this ultimate nature experience!
The ''Sacred Sites and Pilgrimage Routes in the Kii Mountain Range'' is registered as a UNESCO World Heritage Site and will celebrate its 20th anniversary in 2024.' where id = 'DRSqccFZ5LPn2cqE-Kuix';
update content_bodies set title = '紀州浪漫 2023春　日本とトルコ　友好の原点の地へ', description = '日本とトルコ、遠く離れた両国の固い絆。明治期に串本沖で起きたトルコ船籍「エルトゥールル号」の遭難事件を知ると、その理由が見えてくる。歴史に思いを馳せながら、美しい海景を心ゆくまで眺めたい。' where id = 'OcZjh8XBhBY0mgX928Ks4';
update content_bodies set title = 'Kishu Romance Spring 2023: To the Land of Friendship between Japan and Turkey', description = 'The strong bond between Japan and Turkey, two countries far apart. Understanding the shipwreck incident of the Turkish vessel ''Ertuğrul'' that occurred off the coast of Kushimoto during the Meiji period reveals the reason behind it. While reflecting on history, I want to gaze at the beautiful seascape to my heart''s content.' where id = '7rmx9yfwSVvAIzDv_dIN5';
update content_bodies set title = '紀州浪漫2022秋　秋は和歌山でレトロモダン探しの旅', description = '世界遺産エリア（熊野）にある新宮市は、大正・昭和初期を代表する建築家 西村伊作のふるさと。今もなお西村伊作ゆかりのレトロモダンな建築物が残る芸術と文化が薫るまちです。秋は、世界遺産巡りに加えて、フォトジェニックな建築探訪をしながら文化に触れてみませんか。

観光情報誌「紀州浪漫」では、他にもレトロモダンな建築を訪ねる旅を紹介しています。
こちらでチェック！↓↓↓
https://www.wakayama-kanko.or.jp/plan-your-trip/pamphlet/

