update content_bodies set title = '紀州浪漫 2021夏 「和歌山でSUP体験」', description = '和歌山県北部に位置する和歌山市和歌浦はウインドサーフィンやヨットなどのマリンスポーツのメッカ。セーリングのナショナルトレーニングセンターも建つほどの好条件の海で、気軽にSUPも楽しめます。体験メニューや周辺グルメ情報などの詳細は６月１日発行の紀州浪漫夏号で紹介しています。' where id = 'Lb47ycMJ4pQG0zwPunTCW';
update content_bodies set title = 'Kishu Romance Summer 2021: ''SUP Experience in Wakayama''', description = 'Wakayama City, located in the northern part of Wakayama Prefecture, is a mecca for marine sports such as windsurfing and yachting. With favorable sea conditions that even host a national training center for sailing, you can easily enjoy SUP as well. Details on experience menus and local gourmet information are featured in the Kishu Romance Summer issue published on June 1.' where id = 'SPtEGo6DpptbEnLEbZ2-5';
