update content_bodies set title = 'Cycling Kingdom Wakayama: Riding WAKAYAMA800 - From Irokawa to the Scenic Ride to the World Heritage Site of Nachi Falls', description = 'As you ride from Irokawa to Myohosan Amida Temple, you''ll be greeted by the breathtaking views of Kumano-nada! After enjoying the reward for your hard work, you''ll stop by the World Heritage Site ''Nachi Falls'' to conclude your cycling journey in Kumano.' where id = 'JOuBeADrt6BStx3LTnpAo';
