update content_bodies set title = 'Cycling Kingdom Wakayama: Riding WAKAYAMA800 - A Stunning View of White and Blue from Shirazaki Coast to the Old Town of Yuasa and Minoshima Fishing Port', description = 'Cycling from Shirazaki Coast, where the contrast of the pure white rocks and deep blue sea is beautiful, to Arita City. Along the way, we stop by the old town of Yuasa, known for soy sauce brewing, and after passing the Arita Mikan Highway with a view of the Arita sea, we reach the newly established spot ''Hama no Utase'' at Minoshima Fishing Port. The cyclist is the popular cycling influencer Yukari Hirano.' where id = 'cBiCGhCN-tS-Ol2_IOfnr';
update content_bodies set title = 'なまら寒い、冬が来た。', description = '上富良野町に冬が来た

