update content_bodies set title = 'かみふらの桜づつみ夜桜ウォーク', description = '【日時】
令和4年5月1日（日）~5月3日（火）、6日（金）、7日（土）
午後6時45分～8時30分迄　開催
【場所」
さくら堤遊歩道（約500M）
パーラーラッキーズ上富良野店付近から、国道237号線しんえい橋の間、富良野川沿いの桜をライトアップ。
コロナ禍で遠出が出来ない中、身近な場所で町民の心を癒してくれる隠れた桜スポットです。「健康づくり推進のまち上富良野町」では、富良野川沿いの町民の散歩コース桜並木の遊歩道に、今年は桜が咲く夜に魔法をかけました。天気が良くない日もありましたが沢山の町民に楽しんでいただきました。

#上富良野
#島津公園
#桜つつみ' where id = 'YsqbMgZNYniGZ619lxSb5';
update content_bodies set title = 'Kamifurano Cherry Blossom Tsutsumi Night Sakura Walk', description = '[Date]
From May 1 (Sunday) to May 3 (Tuesday), May 6 (Friday), and May 7 (Saturday)
From 6:45 PM to 8:30 PM
[Location]
Sakura Tsutsumi Promenade (approximately 500M)
Illuminating the cherry blossoms along the Furano River between Parlor Luckies Kamifurano and the Shin''ei Bridge on National Route 237.
In the midst of the COVID-19 pandemic, when traveling far is difficult, this hidden cherry blossom spot heals the hearts of the townspeople in a familiar place. In ''Kamifurano Town, a town promoting health,'' we have cast a spell on the cherry blossom promenade, a walking course for residents along the Furano River, to bloom at night this year. Although there were some days with bad weather, many townspeople enjoyed the event.

#Kamifurano
#Shimizu Park
#Cherry Blossom Tsutsumi' where id = 'CIF8BX8YGwIfXtd9RPJAT';
