update content_bodies set title = 'LIVE 35th北の大文字カウントダウン2021－2022 北海道上富良野町', description = '「北の大文字」は、年の暮れから年の初めである元旦午前0時、上富良野町内を一望する日の出公園の斜面に、縦70m・横50mの「大」の文字を描いた鉄杭300本に、かみふらの神社から採火した御神火を次々に灯し、雪一面の暗闇斜面に大文字を浮かび上がらせるという、雪国ならではの幻想的かつ雄大なイベントであり、今や上富良野町・富良野沿線の大晦日の風物詩として毎年、地域住民に定着しています。
　今年で35回を迎え、大の文字と花火で幻想的な中にも躍動感を演出し新しい年を祝い、共に誓いを行う機会とします。
　昨年に引き続き新型コロナウイルス感染症の一日も早い終息を合わせて願い、無観客での開催とします。また、その様子をライブ配信することにより、全世界へ上富良野町の魅力を配信いたします。

第35回北の大文字　～イベントスケジュール～
23：35　ライブ中継スタート
23：45　イベント開始／レーザー＆ムービングショー
23：51　大松明に御神火を灯す
23：53　御神火出発式
23：59　30秒前よりカウントダウン開始（ライブ配信の為時刻に遅延が生じます）
00：00　大文字に点火
00：05　上富良野町長挨拶
00：08　大文字花火打ち上げ・レーザー＆ムービングショー
00：15　イベント終了
00：30　ライブ配信終了

※お願い　日の出ラベンダー園での無許可でのドローンの撮影は禁止されています。
＃北の大文字　＃花火　＃カウントダウン' where id = '4eBTaZS_tUp7KYQ11_Tti';
update content_bodies set title = 'LIVE 35th Northern Daimonji Countdown 2021-2022 Kamifurano Town, Hokkaido', description = '"Northern Daimonji" is a spectacular event unique to snowy regions, where at midnight on New Year''s Day, a 70m tall and 50m wide character ''Dai'' is illuminated on the slope of Hinode Park, overlooking the town of Kamifurano. This is achieved by lighting 300 iron stakes with the sacred fire taken from Kamifurano Shrine, creating a stunning visual of the character glowing against the dark snowy slope. This event has become a traditional New Year''s Eve spectacle for the local residents of Kamifurano and the Furano area. This year marks the 35th edition, where we will celebrate the new year with a dynamic display of the ''Dai'' character and fireworks, providing an opportunity for a collective vow. In light of the ongoing COVID-19 pandemic, we will hold the event without an audience, while live streaming the event to share the charm of Kamifurano Town with the world.

35th Northern Daimonji - Event Schedule -
23:35 Live broadcast starts
23:45 Event begins / Laser & Moving Show
23:51 Lighting the sacred fire on the large torches
23:53 Sacred fire departure ceremony
23:59 Countdown begins 30 seconds prior (there may be delays due to live streaming)
00:00 Ignition of the Daimonji
00:05 Greeting from the Mayor of Kamifurano
00:08 Daimonji fireworks display / Laser & Moving Show
00:15 Event ends
00:30 Live broadcast ends

*Note: Unauthorized drone photography at Hinode Lavender Park is prohibited.
#NorthernDaimonji #Fireworks #Countdown' where id = 'jKLIBPCrx29kPzkCQN_G1';
update content_bodies set title = '2021.06.19 雪渓の中を富良野岳へ向け登山道整備', description = '6月20日に予定していた、第43回十勝岳山開きはコロナ禍の中中止となりましたが、十勝岳安全祈願祭、コース整備は有志の方の協力で行いました。
残雪があるため、特にカミホロ分岐から富良野岳稜線分岐間の、富良野岳寄りの方に残雪が多くみられました。
アイゼンは必要ないですが、滑りやすくなっているため、足を取られやすいので、注意しながら登山して頂きたいです。



