update content_bodies set title = '2021.06.19 Trail Maintenance Towards Furano Dake Through the Snowy Valley', description = 'The 43rd Tokachidake Mountain Opening, scheduled for June 20, was canceled due to the COVID-19 pandemic, but the Tokachidake Safety Prayer Ceremony and trail maintenance were carried out with the cooperation of volunteers.
Due to remaining snow, particularly between the Kamihoro junction and the Furano Dake ridge junction, there was a lot of snow observed closer to Furano Dake.
Crampons are not necessary, but the trail has become slippery, so please be cautious as you hike.' where id = 'f2sua0fM-Os9aCx9JtM0n';
