update content_bodies set title = 'KAMIFURANO LIGHTING-UP & FIREWORKS ONLINE 2020', description = '★★★ 潤いと癒しを与える、夜のラベンダー園 ★★★
上富良野町のラベンダー畑は、今見ごろを迎えています。
例年であれば国内や世界各国からから紫の絨毯を見ようとたくさんの観光客が来町します。
しかし...今年はコロナ禍で北海道に来れない方も多く、せめてラベンダーの香りだけでもと「ラベンダーオーナー」に申し込まれる方も多くいます。
そんな中、こよなく上富良野町を愛してくださる全世界の方へ、まさに見頃のラベンダー畑を、そして今まで見たことのない演出でライブ配信します。
夜の幻想的なラベンダーをご自分の一番好きな特等席で、どうぞお楽しみください！
ラベンダーが無数のランタンキャンドルで彩られ、さらに多数のライトアップと打上花火が全世界に向けYouTubeでライブ配信されます。

★★★ お願い ★★★
当日会場は駐車場を含めて立ち入り禁止となります。
会場内ではライブの音や音楽は流れません、ご自宅のYouTubeが見られるテレビかパソコン、携帯端末でご覧ください。
会場周辺の路駐も通行の妨げになりますし、警察のパトロールも行いますのでご遠慮ください。
※天候・ネット環境により配信が切断・中止になる場合がございます。

★★★ Youtubeライブによる、特別WEB中継 ★★★
「KAMIFURANO LIGHTING-UP ＆ FIREWORKS ONLINE 2020」のWEB中継は、動画共有サイト「Youtube」の（一社）かみふらの十勝岳観光協会チャンネルにて行います。かみふらの十勝岳観光協会チャンネルに登録すると、中継を開始したときに通知を受け取ることができるので、この機会にぜひ、ご登録ください！

★★★ イベントライブ配信＆スペシャルゲスト ★★★
スペシャルゲストには牧野由依さんが登場します。また、ライブ配信中に、Nene＆Waka（ネネ＆ワカ）によるイベントライブがあります！どうぞお楽しみに♪(無観客）

★★★ プログラム ★★★
・YouTubeライブ配信スタート
　かみふらの十勝岳観光協会YouTubeチャンネルで配信
・牧野由依「かみふらの観光PR大使」ビデオメッセージ
　2018年に「かみふらのPR大使」に就任し、今回継続の委嘱とライブショーへのメッセージをいただきます
・ラベンダーライティングショー
　ラベンダー園を無数のランタンキャンドルで彩り、ライトアップで幻想的な世界演出します
・ラベンダーライブショー
　旭川のダンス＆ボーカルグループ「Nene＆Waka」の無観客ライブショー
・ラベンダーライティング＆花火ショー
　ラベンダー畑一面に照らされたライティングと花火の競演
・YouTubeライブ配信終了

日 時
令和2年7月22日(水)　19：30～
ラベンダー園が荒天等のため実施できない場合は、中止とします。
実施の可否の判断は、原則として当日の午後５時に行います。

会 場
上富良野町内のラベンダー園
※会場のラベンダー園には、午後５時から入場できません。

主 催
一般社団法人　かみふらの十勝岳観光協会

