update content_bodies set title = 'KAMIFURANO LIGHTING-UP & FIREWORKS ONLINE 2020', description = '★★★ A Night Lavender Garden that Provides Moisture and Healing ★★★
The lavender fields in Kamifurano Town are now in full bloom.
Typically, many tourists from Japan and around the world come to see the purple carpet.
However... this year, due to the COVID-19 pandemic, many people are unable to visit Hokkaido, and many have applied to be "Lavender Owners" just to enjoy the scent of lavender.
In this context, we will live stream the lavender fields, which are at their peak, to all the people around the world who love Kamifurano Town, with a performance like never before.
Please enjoy the fantastical lavender at night from your favorite special seat!
The lavender will be adorned with countless lantern candles, and numerous light displays and fireworks will be live streamed on YouTube to the whole world.

★★★ Request ★★★
The venue will be off-limits on the day, including the parking lot.
There will be no live sound or music at the venue, so please watch on your TV, computer, or mobile device that can access YouTube at home.
Parking on the streets around the venue will obstruct traffic, and police patrols will be conducted, so please refrain from doing so.
*The stream may be interrupted or canceled due to weather or internet conditions.

★★★ Special WEB Broadcast via YouTube Live ★★★
The WEB broadcast of "KAMIFURANO LIGHTING-UP & FIREWORKS ONLINE 2020" will be conducted on the YouTube channel of the Kamifurano Tokachidake Tourism Association. By subscribing to the Kamifurano Tokachidake Tourism Association channel, you will receive notifications when the broadcast starts, so please take this opportunity to subscribe!

★★★ Event Live Streaming & Special Guest ★★★
Special guest Yui Makino will appear. Additionally, during the live stream, there will be an event live performance by Nene & Waka! Please look forward to it♪ (No audience)

★★★ Program ★★★
・YouTube Live Streaming Starts
　Streaming on the Kamifurano Tokachidake Tourism Association YouTube channel
・Video Message from Yui Makino, "Kamifurano Tourism PR Ambassador"
　She was appointed as the "Kamifurano PR Ambassador" in 2018 and will provide a message for the continuation of her appointment and the live show.
・Lavender Lighting Show
　The lavender garden will be adorned with countless lantern candles, creating a fantastical world with lighting.
・Lavender Live Show
　A no-audience live show by the dance and vocal group "Nene & Waka" from Asahikawa.
・Lavender Lighting & Fireworks Show
　A competition of lighting illuminating the entire lavender field and fireworks.
・YouTube Live Streaming Ends

Date and Time
July 22, 2020 (Wednesday) 19:30～
If the lavender garden cannot be held due to inclement weather, it will be canceled.
The decision on whether to hold the event will be made at 5 PM on the day, in principle.

Venue
Lavender garden in Kamifurano Town
*Entry to the lavender garden at the venue will not be allowed after 5 PM.

Organizer
General Incorporated Association Kamifurano Tokachidake Tourism Association

Support and Cooperation
Kamifurano Town, Kamifurano Promotion Corporation

*Request: Unauthorized drone photography at the Hinode Lavender Garden is prohibited.' where id = 'xqpKHqF3c2JS7MNwSQF3O';
