update content_bodies set title = 'Tokachidake Skyline Route Opening Ceremony', description = 'The road known as the Tokachidake Skyline, or the Tokachidake Onsen Biei Line, will once again be open for traffic between Tokachidake Onsen and Shirogane Onsen before this year''s Golden Week, after being closed for six months.
