update content_bodies set title = '🌙宮島夜市「宮島つき祭り」開催🌙 #北広島町', description = '🌙3/8、3/9の２日間、宮島夜一「宮島つき祭り」が開催されました🌙

今年で3回目の開催となった宮島夜市。
北広島町も参戦させて頂きました🔥🔥

わが町からは「へんぽこ茶屋」さんが出店！お肉の焼ける香ばしい香りに誘われてお客さんが絶えません！
自家製のお米で作られたお餅は、保存料を使っていないのでつきたてもちもち。
海外の方も美味しそ〜うにいちご大福を頬張っていました🍓

もちろん神楽は大盛況！
わが町からは山王神楽団さんが3回目の出演となりました。
山王さんと天神さんの熱演に、お客さんも釘付け。
わが町が誇る伝統芸能をご覧あれ！！と熱い気持ちで司会をさせて頂きました☺️
幕間の観光PRステージでは、1日目は観光大使の月山翔雲さんが「ひろしま牡蠣のうた」と「おいでよ！キタひろ」で会場を盛り上げて下さいました🦪

2日目は広島県立廿日市西高等学校のダンス部のみんなが一緒に踊ってくれました。ステージを華やかに、そして盛り上げてくれてありがモ〜！！

北広島町の観光ブースでは、SNSをフォローしてくださった方にノベルティをプレゼント！
北広島町遊びに行ったよ〜TikTok見てるよ〜と言って頂き、励みになりました。

動画をきっかけとして、ぜひ北広島町へ遊びに来て下さいね！

大盛況だった宮島夜市「宮島つき祭り」
たくさんの方の笑い声と拍手が今も耳に残っています。
宮島を夜まで楽しんで頂くために始まった宮島夜一。
ぜひ来年もお越し下さい✨️✨️

