update content_bodies set title = '🌙Miyajima Night Market ''Miyajima Tsuki Festival'' Held🌙 #Kitahiroshima Town', description = '🌙On March 8th and 9th, the Miyajima Night Market ''Miyajima Tsuki Festival'' was held🌙

This year marks the third edition of the Miyajima Night Market.
Kitahiroshima Town also participated! 🔥🔥

From our town, ''Henpoko Chaya'' set up a stall! The savory aroma of grilled meat attracted a steady stream of customers!
The rice cakes made from our homemade rice are fresh and chewy, without any preservatives.
International visitors were happily munching on strawberry daifuku 🍓

Of course, the Kagura performances were a huge success!
From our town, the Sannou Kagura Group made their third appearance.
The passionate performances by Sannou and Tenjin captivated the audience.
I hosted with a heartfelt desire to showcase our town''s proud traditional arts!! ☺️
During the intermission tourism PR stage, on the first day, our tourism ambassador Shouun Tsukiyama energized the venue with ''Hiroshima Oyster Song'' and ''Come on! Kita Hiro'' 🦪

On the second day, the dance club from Hiroshima Prefectural Hatsukaichi Nishi High School danced together with us. Thank you for making the stage vibrant and exciting!

At the Kitahiroshima Town tourism booth, we gave away novelties to those who followed us on social media!
Hearing people say, ''I visited Kitahiroshima!'' and ''I’m watching your TikTok!'' was encouraging.

Please come visit Kitahiroshima, inspired by the videos!

The Miyajima Night Market ''Miyajima Tsuki Festival'' was a great success.
The sounds of laughter and applause from many people still linger in my ears.
The Miyajima Night Market was started to allow everyone to enjoy Miyajima until nightfall.
We hope to see you again next year! ✨️✨️

