This chiffon roll is perfect for celebrating Hina Matsuri, available for pre-order only on March 2nd and 3rd.
Pre-orders are accepted until February 27th (Thursday)! 

Be sure to have this specially crafted roll cake on your celebration table. (12cm / 2000 yen including tax)

Reservations can be made via DM to Niwa no Niwatori or at the store!

[Niwa no Niwatori]  
Address: 1299 Arita, Kita Hiroshima Town, Yamagata District, Hiroshima Prefecture, 731-1534  
