update content_bodies set title = '広島でいちご狩りするならここ！！🍓🍓 #北広島町 #アウトドア #旅行#いちご', description = 'いちご好きの皆さんーー！！！🍓🍓

北広島町観光協会の職員と広島県観光アシスタント　初代　広島きんさいとの宮内さんで北広島町の豊平どんぐり農園に行ってきました！！

広島きんさいとの宮内さんは、広島の観光やイベントを盛り上げる観光アシスタント。
去年の6月には「壬生の花田植」にも来て頂き、北広島町を愛してくださっています！

いちご大好きな我々を豊平どんぐり農園の謝花さんが案内してくださいました。
３人バージョンのレッツら モー‼️新鮮です😁

広島市内から車で約１時間。
丹精込めて育てられた自慢の9品種が5月下旬までお楽しみ頂けます。
30分の食べ放題で、練乳・チョコソース・ホイップなどのトッピングが持ち込み可能！

いちごが大きすぎて口に頬張ると喋れないのでみんな無言で味わいます。あま〜い。そしてジューシー。

ホイップクリームにたっぷり付けて楽しむいちご…贅沢感がたまりません✨️

広々とした園内通路で、ベビーカーや車椅子でも快適にお過ごし頂けます。

謝花さんいわくいちごが大きくて甘いこの時期が特におすすめだそう！
いちご狩りのご予約、お問い合わせは豊平どんぐり農園さんのＨＰやSNSをご覧下さい！

