update content_bodies set title = 'Scenery of Kitahiroshima Town - The Purple Village', description = '[Yukari®︎, a familiar name from Mishima Foods]
Did you know that the roots of the famous furikake ''Yukari®︎'', known nationwide, are in Kitahiroshima Town?
If Mishima Foods has its roots in Kitahiroshima Town, then Yukari®︎ also has its connection to Kitahiroshima Town.
1. Mr. Tetsuo Mishima, who founded the company in 1949, is from Arita in Kitahiroshima Town.
2. The birthplace of founder Mr. Tetsuo Mishima is now a furikake museum called ''Kusunoki-en''.
3. In front of Kusunoki-en, there is a vast field of red shiso, colored like shiso! Our own farm ''The Purple Village'' is located in Kitahiroshima Town.
And so on... there is a deep connection.

In Kitahiroshima Town, from mid-May, a carpet of shiso spreads across the area, creating a unique scenery just for this time.
*The photo was taken on June 13, 2023.

▼Mishima Foods Co., Ltd. HP▼
https://www.mishima.co.jp/
▼Furikake Museum ''Kusunoki-en''▼
In addition to displaying products from furikake manufacturers nationwide, you can also learn about the origins and manufacturing processes of furikake.
https://www.mishima.co.jp/enjoy/kusunokien/

#Yukari #Furikake #MishimaFoods' where id = 'xYJjQ-Hb0mJ9HOeENpO7W';
update content_bodies set title = '✨四季乃家彩蔵さんのとっておき秋メニューを食べに観光協会職員が行ってきました✨ #北広島町', description = '✨四季乃家彩蔵さんのとっておき秋メニューを食べに観光協会職員が行ってきました✨

夜の彩蔵さんは昼とは違う雰囲気で、石灯籠の優しい灯りに心が和みます。

今回の秋メニューのイチオシは
「米粉シチューのあつあつ」
濃厚で甘いかぼちゃのとろとろシチューの中にはうまみぎっしりのハンバーグが！

肌寒いこの季節は「じゅ～じゅ～」「グツグツ」の音に心惹かれます。

どのお料理も目でも楽しめる「美しさ」があり、旬の食材が大将の技で更に美味しくなり、お皿の上で輝いています。

松茸をふんだんに混ぜ込んだきのこご飯は香り豊かで「秋」の恵みを贅沢に堪能できる一品。※松茸は別途地価

大将の自信たっぷりの「にやり顔」で美味しいのが伝わってきますね☺

前回の20周年の動画で、大将の人気がますます上がったようで、今回も渋い名演技にまたファンが増えそうです！

とっておき秋メニュー、ぜひ食べに来て下さい🍂

