update content_bodies set title = '✨The staff of the tourism association visited Shikinoya Ayakura to try their special autumn menu✨ #KitaHiroshimaTown', description = '✨The staff of the tourism association visited Shikinoya Ayakura to try their special autumn menu✨

The evening atmosphere at Ayakura is different from the daytime, with the gentle light of the stone lanterns bringing a sense of calm.

The highlight of this autumn menu is the "Hot Rice Flour Stew."
Inside the rich and sweet pumpkin stew is a hamburger packed with umami!

In this chilly season, the sounds of "sizzle" and "bubble" draw our hearts.

Each dish has a "beauty" that is enjoyable to the eyes, and seasonal ingredients become even more delicious with the chef''s skill, shining on the plate.

The mushroom rice, generously mixed with matsutake, is fragrant and allows you to indulge in the blessings of "autumn." *Matsutake is priced separately.

You can feel the deliciousness conveyed through the chef''s confident "smirk" ☺

It seems that the chef''s popularity has increased even more after the previous 20th-anniversary video, and this time, his subtle yet impressive performance is likely to attract more fans!

Please come and try the special autumn menu 🍂

【Shikinoya Ayakura】

Address: 258-1 Kurazako, Kita Hiroshima Town, Yamagata District, Hiroshima Prefecture
