update content_bodies set title = '《 Short01 》この町は、冬の楽しみ方を知っている。', description = '北広島町の映像制作会社うえひろやスタジオと観光協会がタッグを組み、「冬の北広島町」をPRする動画の長編と短編を作成した。

▶短編（short01～short03）
気軽に見れる、ポップなテイストで作成。長編にはないシーンも盛り沢山！
《short02》https://youtu.be/dsj2EYht-HQ
《short03》https://youtu.be/Fm4Pz8sq1TQ

▶長編のテーマ【冬の北広島町には、描きたくなる景色がある。】
今までにない「冬」の北広島町の魅力を詰め込んだドラマ風の動画となっております。
《 long 》https://youtu.be/S-UUqABvGYI
～ story ～
画家の女性がスランプに陥り、沈んでいるところに一件のLINEが。気分転換に冬の北広島町へと向かいます。不安がにじむ表情の彼女ですが、冬ならではのアクティビティや、息をのむ絶景に心が動かされていきます。彼女はまた絵が描けるようになるのでしょうか・・・。

爽快な音楽とともに変化していく彼女の心境と美しい冬の景観にご注目ください。


