update content_bodies set title = '《 Short01 》This Town Knows How to Enjoy Winter.', description = 'A video production company in Kitahiroshima Town, Uehiroya Studio, has teamed up with the tourism association to create both long and short videos promoting ''Winter in Kitahiroshima Town.''

▶Shorts (short01 to short03)
Created in a pop style that is easy to watch. Packed with scenes not found in the long version!
《short02》https://youtu.be/dsj2EYht-HQ
《short03》https://youtu.be/Fm4Pz8sq1TQ

▶Long Version Theme [In Winter, Kitahiroshima Town Has Scenery That Inspires You to Create.]
This is a drama-style video filled with the charm of ''Winter'' in Kitahiroshima Town like never before.
《 long 》https://youtu.be/S-UUqABvGYI
～ story ～
A female painter falls into a slump and is feeling down when she receives a LINE message. She heads to Winter Kitahiroshima Town for a change of pace. Although she shows a worried expression, she becomes captivated by winter-specific activities and breathtaking views. Will she be able to paint again...?

Please pay attention to her changing state of mind along with refreshing music and the beautiful winter scenery.

Planning and Production: (General Incorporated Association) Kitahiroshima Town Tourism Association
Filming and Editing: Uehiroya Studio《HP》http://uehiroya.com/
Production Period: December 2022 to March 2023

