update content_bodies set title = '✨開店20周年を迎えた「四季乃家 彩蔵」さんに花田舞太郎と観光協会職員がお昼ご飯を食べに行ってきました✨', description = '✨開店20周年を迎えた「四季乃家 彩蔵」さんに花田舞太郎と観光協会職員がお昼ご飯を食べに行ってきました✨

玄関に入ると、季節の花、ひまわり🌻がお出迎え。

洗練された美しさと、心がほどける「和」の空間がブレンドされた店内は女将のセンスが光ります。

今回食べたのは10食限定の蕎麦ランチ。(蕎麦ランチの詳細は彩蔵さんのSNSをチェック✅)
大将が厳選した旬の食材は、美しく、そして言わずもがな絶品。

とうもろこしご飯を頬張ると、ふわわっと甘いとうもろこしが鼻に抜けます。旬のものを食べると、その季節を元気に乗り越えるエネルギーで満たされますね。

こだわり抜いた海の幸、山の幸を上品な空間でゆっくりと堪能できる「四季乃家 彩蔵」さんはこの8月で20周年🎉

「ありがたいことに、完全予約制でも20年続いている。
その理由は……お店に来てみてね♡」
とお茶目な大将は言います😚

そうです、来て、食べる。それだけでたくさんの方に愛される理由がわかります。

大切な人との「特別」な時間をぜひ「四季乃家 彩蔵」さんでお過ごしください。

【四季乃家 彩蔵(しきのいえあやくら)】
