update content_bodies set title = '✨We visited ''Shikinoya Ayakura'', celebrating its 20th anniversary, for lunch with Maitaro Hanada and the tourism association staff✨', description = '✨We visited ''Shikinoya Ayakura'', celebrating its 20th anniversary, for lunch with Maitaro Hanada and the tourism association staff✨

Upon entering the entrance, seasonal flowers, sunflowers 🌻, greet you.

The interior, blending refined beauty with a relaxing ''Japanese'' atmosphere, showcases the sense of the owner.

What we had this time was a limited 10 servings soba lunch. (For details on the soba lunch, check Ayakura''s SNS ✅)
The seasonal ingredients carefully selected by the chef are beautiful and, needless to say, exquisite.

As I took a bite of the corn rice, the sweet corn wafted through my nose. Eating seasonal foods fills you with the energy to cheerfully overcome that season.

At ''Shikinoya Ayakura'', you can leisurely enjoy carefully selected seafood and mountain delicacies in an elegant space, and this August marks its 20th anniversary 🎉

"Fortunately, we have been fully reservation-based for 20 years. The reason is... come to the restaurant and see for yourself♡" says the playful chef 😚

That''s right, come and eat. Just that alone reveals why so many people love it.

Please spend a ''special'' time with your loved ones at ''Shikinoya Ayakura''.

【Shikinoya Ayakura】
Address: 258-1 Kurazako, Kitahiroshima-cho, Yamagata-gun, Hiroshima Prefecture
Phone: 0826-72-6361
Closed: Wednesdays and Thursdays *Irregular holidays in winter
Takeout: Reservations required from one month to two days in advance
Business hours: 11:30 AM to 3:00 PM (enter by 1:00 PM)
6:00 PM to 10:00 PM (enter by 8:00 PM)

⭐️Please check Ayakura''s SNS for the dates of the soba lunch.
The dates in August are the 26th, 27th, and 28th.
Be sure to enjoy the carefully crafted soba, limited to 10 servings 🙏

BGM/shimtone ''Marshmallow Cloud''
