update content_bodies set title = '✨北広島町のスキー場「ユートピアサイオト」の期間限定「夏のアクティビティ」を舞太郎と観光協会職員が体験してきました！！✨', description = '✨北広島町のスキー場「ユートピアサイオト」の期間限定「夏のアクティビティ」を舞太郎と観光協会職員が体験してきました！！✨

今回体験したのは、滑車を使って木々の間に張られたロープを滑り降りる「ジップライン」と、ゲレンデや林道を駆け巡る「バギーアドベンチャー」の２つ。

絶叫が苦手な職員はジップラインのスタート地点の高さにビビり、へっぴり腰でなんとかジャンプ。

思い切っていってしまえばもう風を体全体で感じて爽快感を楽しむだけ。

空中からの景色を楽しみながら鳥ってこんな気持ちなのかな…なんて考える余裕まで出てきました☺全部で6コースあるので次は制覇するぞ！！

そして個人的にジップラインよりドキドキした「バギーアドベンチャー」。

しっかりと操作を教えてもらい、いざ出発。親鳥を追う雛のように、支配人の山元さんに必死についていきます。

一番人気のコース「天空バギーアドベンチャー」走行距離4,000m、標高1,000mを登っていき、頂上へ。
そこには、日本海まで見渡せる絶景が広がっていました。

深呼吸して、大自然のパワーを体いっぱいに吸い込みます。なんだか私自身がレベルアップような達成感と感動がありました。

この夏はぜひユートピアサイオトで、自分の殻を破いちゃいましょう。

営業日はホームページをチェックしてください！　

