update content_bodies set title = 'ふけかけの工場見学に行ってみた。', description = '先日、工場の見学もさせていただきました！！

【ゆかり®︎でおなじみ三島食品との縁(ゆかり)】
今や全国にその名が知られる、ふりかけの大エース『ゆかり®︎』
そのゆかり®︎を作っている三島食品のルーツが北広島町にあるって、みなさんご存知ですか〜？
三島食品のルーツが北広島町ならば、ゆかり®︎の所縁(ゆかり)も北広島町
①昭和24年に創業された三島哲男さんは北広島町有田の出身
②創業者 三島哲男さんの生家があった場所は、現在『楠苑』というふりかけの資料館になっています
③楠苑の前に広がる辺り一面シソ色の赤シソ畑！自社農園『紫の里』を北広島町に置いています
などなど…深〜い縁(ゆかり)があるのです。

北広島町では5月中旬からシソ色のじゅうたんが辺り一面に広がり、今だけの景色が広がります。
※撮影は2023年6月13日

▼三島食品（株）HP▼
https://www.mishima.co.jp/
▼ふりかけ資料館「楠苑」▼
全国のふりかけメーカーの商品を展示するほか、ふりかけの起源や製造工程も学べます。
https://www.mishima.co.jp/enjoy/kusunokien/

#ゆかり #ふりかけ #三島食品' where id = '3pGIyX9wYwet-vfEb-BwH';
update content_bodies set title = 'I Went on a Factory Tour of Furikake.', description = 'The other day, I had the opportunity to tour the factory!!

【The Connection with Mishima Foods, Famous for Yukari®︎】
Did you know that the roots of Yukari®, the big ace of furikake now known nationwide, are in Kitahiroshima Town?
If Mishima Foods has its roots in Kitahiroshima Town, then Yukari®︎ also has its connection there.
1. Mr. Tetsuo Mishima, who founded the company in 1949, is from Arita in Kitahiroshima Town.
2. The place where the founder, Mr. Tetsuo Mishima, was born is now a furikake museum called ''Kusunoki-en''.
3. The area in front of Kusunoki-en is filled with red shiso fields in a shiso color! They have their own farm, ''Murasaki no Sato'', located in Kitahiroshima Town.
And so on... there is a deep connection.

In Kitahiroshima Town, from mid-May, a carpet of shiso color spreads all around, creating a unique scenery that can only be seen now.
*The photo was taken on June 13, 2023.

▼Mishima Foods Co., Ltd. HP▼
https://www.mishima.co.jp/
▼Furikake Museum ''Kusunoki-en''▼
In addition to displaying products from furikake manufacturers nationwide, you can also learn about the origins and manufacturing processes of furikake.
https://www.mishima.co.jp/enjoy/kusunokien/

#Yukari #Furikake #MishimaFoods' where id = 'L2yypgKoBxN9boASdAhmU';
update content_bodies set title = '吉川氏ゆかりの地', description = '【北広島町豊平地域】
戦国時代にこの地域を支配した吉川氏の史跡も数多く残っており、武将の足跡 や民衆のいぶきを感じることができます。

【吉川元春館跡歴史公園】
吉川元春の隠居所として築かれた館の跡。多くの建物跡やトイレ、井戸、庭園などが見つかった。復元した台所建物では、カマドや炉を使って煮炊もできる。

【戦国の庭歴史館】
史跡吉川氏城館跡全体を案内する展示施設。館跡出土品や中世の生活についての展示、甲冑の展示があり、甲冑の試着体験もできる。
▶広島県山県郡北広島町海応寺255-1
▶0826-83-1785
▶https://www.town.kitahiroshima.lg.jp/site/bunkazai/1779.html

※館内許可を得て撮影しております。

#吉川元春
#毛利家
#歴史' where id = 'I6RgM6q6X_Brs8chfF4MG';
update content_bodies set title = 'The Land Associated with the Yoshikawa Clan', description = '【Toyohira Area, Kitahiroshima Town】
Numerous historical sites of the Yoshikawa clan, who ruled this area during the Sengoku period, remain, allowing visitors to feel the footsteps of the samurai and the breath of the people.

【Yoshikawa Motoharu Residence Ruins Historical Park】
The ruins of a residence built as a retirement home for Yoshikawa Motoharu. Many building foundations, toilets, wells, and gardens have been discovered. In the restored kitchen building, cooking can be done using a kamado and a hearth.

【Sengoku Garden Historical Museum】
An exhibition facility that guides visitors through the entire site of the Yoshikawa clan''s castle ruins. It features displays of artifacts unearthed from the site, exhibitions on medieval life, and armor displays, with the opportunity to try on armor.
▶255-1 Kaiouji, Kitahiroshima Town, Yamagata District, Hiroshima Prefecture
▶0826-83-1785
▶https://www.town.kitahiroshima.lg.jp/site/bunkazai/1779.html

*Photography is permitted inside the facility.' where id = 'yAs0dv8GG0kD6i7m4FhU0';
