update content_bodies set title = '[Kita-Hiroshima Town] chalkart.Studio.Ape', description = '[Chalk art at a temple approximately 260 years old (Senkyoji)]
Chalk art is a new form of art that originated in Australia, where vibrant oil pastels are used to draw on a special blackboard. Colors are mixed together, and the drawing is done using fingers. Since everything is finished freehand, it has a warmth and an unforgettable charm that captivates those who see it.
Even beginners can feel at ease as they receive gentle guidance!

Address: 2191 Honchi, Kita-Hiroshima Town
Business hours: By reservation only (please contact us for details)
Phone: 090-8930-3014 (Nakano)
Website: http://chalkstudioape.com/' where id = 'xv5k3snUh-9vB33_7_Qr8';
update content_bodies set title = '【北広島町】JB北広島乗馬クラブ', description = '中国自動車道千代田ICから車で10分。JB北広島乗馬クラブは
広島県内はもちろん、県外の乗馬ファンの皆様のご来場をお待ちしています。
馬に乗って草原を颯爽と駆け抜ける…。そんな姿に憧れを抱いている方も多いはず。
馬上から眺める景色の素晴しさは、経験したことのある人だけが分かる喜び。
世界が変わって見えるほどの広がりを感じて頂けます。 そして何よりも馬という動物とふれあうことで得る安らぎ。
緑あふれる自然に恵まれたJB北広島乗馬クラブは、あなたの夢にお応えします。
