update content_bodies set title = '【北広島町】打ち上げ花火ライブ配信（2020.8.1）', description = '８月1日に本地夏祭りが行われる予定でしたが、新型コロナウイルスの影響で中止になりました。しかし、本地地区の住民有志でつくる本地・赤鬼会のみなさんが、約７０発の花火を場所はシークレットで密を防ぎながら打ち上げました。
