update content_bodies set title = '住む人と土地の温もりに間近で触れる。鹿児島県・出水市で農泊体験', description = '鹿児島と熊本の県境に位置する出水（いずみ）市。日本一のツルの渡来地として知られるこの町には、江戸時代の面影を残す武家屋敷群や日本一の大鈴を供える神社など、見どころがたくさんあります。

さらに、出水市の魅力を深く知るならば「農泊」という宿泊スタイルがおすすめです。農山漁村地域に滞在することで、その地域の生活を体験することができるのが農泊のよさ。

出水市の暮らしを身近に感じ、大自然にふれ、独自の食文化を知る。すべてを凝縮したような、1泊2日の旅に出かけましょう。

続きは動画と以下の記事で…

■住む人と土地の温もりに間近で触れる。鹿児島県・出水市で農泊体験（OnTrip JAL）
