update content_bodies set title = 'Experience the warmth of the people and land up close. Agricultural lodging experience in Izumi City, Kagoshima Prefecture', description = 'Izumi City, located on the border of Kagoshima and Kumamoto Prefectures, is known as the number one stopover for cranes in Japan. This town is filled with attractions, including samurai residences that retain the charm of the Edo period and a shrine that houses the largest bell in Japan.

Furthermore, if you want to deeply understand the charm of Izumi City, the lodging style called ''agricultural lodging'' is recommended. By staying in rural areas, you can experience the local way of life, which is the beauty of agricultural lodging.

Feel the life of Izumi City up close, connect with nature, and learn about its unique food culture. Let''s embark on a condensed journey of 1 night and 2 days that encompasses it all.

For more details, check out the video and the article below...

