update content_bodies set title = '「燃ゆる感動かごしま国体」出水市開催1000日前記念イベント', description = '平成３０年１月７日（日）で、「燃ゆる感動かごしま国体」開催まであと1000日になりました。そこで、市民の皆様とかごしま国体を盛り上げるべく、「出水市開催1000日前記念イベント」を開催しました。
 　国体までのカウントダウンボードの除幕や競技団体を代表しての決意表明、市民運動開始宣言、国体ダンス「ゆめ～KIBAIYANSE～」の披露などが行われ、国体ムードもいよいよ高まってきました。' where id = 'bDvSnp1qJFaKohbQEoYwC';
update content_bodies set title = '1000 Days Until the ''Burning Passion Kagoshima National Sports Festival'' Event in Izumi City', description = 'On January 7, 2018 (Sunday), it became 1000 days until the ''Burning Passion Kagoshima National Sports Festival'' is held. To energize the citizens and promote the Kagoshima National Sports Festival, we held the ''Izumi City 1000 Days Before Event''.

The event included the unveiling of the countdown board to the National Sports Festival, a declaration of determination representing the sports organizations, a declaration to start citizen movements, and a performance of the National Sports Festival dance ''Yume~KIBAIYANSE~'', which has heightened the atmosphere for the National Sports Festival.' where id = 'w2PTJS-UyVzP1pv6QLrtL';
