update content_bodies set title = '71st Honjo River Festival Fireworks Festival', description = 'This year marks the revival of the Niagara fireworks after four years, along with the reopening of food stalls and paid seating! 
We will continue the YouTube live streaming that we challenged last year. 
This year, the NTT streaming team will provide full support! 
Additionally, we are excited about our first attempt to create a special metaverse venue utilizing virtual space, aiming for a fusion of the real and digital worlds!

