update content_bodies set title = '【由利本荘市】2023年4月採用地域おこし協力隊募集PV【観光振興】', description = '秋田県由利本荘市の令和５年度４月採用の地域おこし協力隊募集ＰＲ動画です。
秋田県の南端、山形県にまたがる鳥海山。
由利本荘市は鳥海山の北麓に位置し、内陸から日本海に接する秋田県一の広さをもつ自治体です。
由利本荘市の観光は広大なアウトドアフィールドを活かしたアウトドアレジャーですが、プレイヤーの高齢化や施設の老朽化などの課題を抱え、世代交代と新たなアウトドアアクティビティ拠点の再整備に向けた取り組みを進めています。
そんな次世代の由利本荘市のアウトドアを支える人材を募集しています。
詳しくは、市ホームページをご覧ください。
https://www.city.yurihonjo.lg.jp/kanko/13403

私たちと一緒に由利本荘市の新しい観光を作りましょう。
あなたの挑戦をお待ちしております。

企画・制作
由利本荘市
