update content_bodies set title = '四国松山[松山市公式観光WEBサイト]', description = '「四国瀬戸内松山」松山市オフィシャル観光WEBサイト
https://matsuyama-sightseeing.com

松山市は、穏やかで美しい瀬戸内海に面しており、一年を通じて気候が温暖で雨の少ない過ごしやしい地域です。利便性に優れた街の西側は海、東側には山があり、都会の快適さと田舎ののどかさの両方を合わせもっています。
また、日本最古の名湯といわれる道後温泉をはじめとする温泉や、近代俳句の礎を築いた正岡子規の存在などもあり、「いで湯と城と文学のまち」と言われているほど文化的魅力が豊富。市の中心には、全国でも貴重な江戸時代から残る天守を有する松山城があり、その麓に広がる町には、城下町の文化が息づいています。古くから四国遍路のおへんろさんを迎えてきた町らしく、旅人を温かく迎え入れる「おもてなし」も息づいています。' where id = '5UCIpIvPc6zhIFhuM-3x4';
update content_bodies set title = 'Matsuyama, Shikoku [Official Matsuyama City Tourism Website]', description = '"Shikoku Setouchi Matsuyama" Official Tourism Website of Matsuyama City
https://matsuyama-sightseeing.com

Matsuyama City faces the calm and beautiful Seto Inland Sea, and it is a pleasant area with a mild climate and little rain throughout the year. The western side of the city, which is highly convenient, is by the sea, while the eastern side has mountains, combining the comforts of urban life with the tranquility of the countryside.
Additionally, the city is rich in cultural attractions, being known as the "town of hot springs, castles, and literature," with the famous Dogo Onsen, said to be Japan''s oldest hot spring, and the presence of Masaoka Shiki, who laid the foundation for modern haiku. At the center of the city stands Matsuyama Castle, which has a valuable Edo-period keep, and the town that spreads at its foot is alive with the culture of a castle town. True to its history of welcoming pilgrims on the Shikoku pilgrimage, the town embodies a warm hospitality that welcomes travelers.' where id = 'IQaLPwgzgH5v52--HBFJt';
update content_bodies set title = '弘前ねぷた300年祭～弘前ねぷたをもっと知ろう！～【資料編】', description = '～歴史と伝統の継承、そして未来へ～

　弘前ねぷたは1722(享保7)年に初めて文献に登場してから、2022(令和4)年に300年という節目を迎えました。
　弘前ねぷた300年祭実行委員会では、弘前ねぷたの歴史と伝統の継承、そして未来へ繋げるため、記念動画【歴史編】【資料編】の2本を制作しました。

【歴史編】はこちらをご覧ください。
https://youtu.be/uKoYJcUFroc

