update content_bodies set title = 'Hirosaki Neputa 300th Festival - Let''s Learn More About Hirosaki Neputa! - [Reference Edition]', description = ' - Inheritance of History and Tradition, and Towards the Future -

The Hirosaki Neputa first appeared in documents in 1722 (the 7th year of the Kyoho era) and celebrated its 300th anniversary in 2022 (the 4th year of Reiwa).
The Hirosaki Neputa 300th Festival Executive Committee has produced two commemorative videos, [History Edition] and [Reference Edition], to pass on the history and traditions of Hirosaki Neputa and connect them to the future.

Please watch the [History Edition] here.
