update content_bodies set title = '熊本県南阿蘇村ふるさと納税・返礼品PRムービー「南阿蘇TEA HOUSE」', description = '熊本県南阿蘇村うまれのハーブティー専門店「南阿蘇TEA HOUSE」。
阿蘇の山々と穏やかな太陽の日差しのもと、豊かな自然の中でハーブの栽培に取り組み、世界各地から厳選したハーブも取り扱い、全てのブレンドを自社で行っています。

良質な水と土、穏やかな日差しと心地よい風。ハーブにとって素晴らしい条件がそろった熊本県南阿蘇村で大切に育てハーブの力を引き出すことで、香り豊かな美味しいハーブができあがります。
※農薬・化学肥料は未使用。JAS認定を受けた安全な農地で栽培されています。' where id = 'Yvfs5zViiYHXE4v7E9IDm';
update content_bodies set title = 'Kumamoto Prefecture Minami-Aso Village Furusato Tax Donation and Return Gift PR Movie ''Minami-Aso TEA HOUSE''', description = 'Herbal tea specialty store ''Minami-Aso TEA HOUSE'' born in Minami-Aso Village, Kumamoto Prefecture.
Under the Aso mountains and gentle sunlight, we engage in herb cultivation in rich nature, handling carefully selected herbs from around the world, and all blends are done in-house.

With high-quality water and soil, gentle sunlight, and pleasant winds, Minami-Aso Village in Kumamoto Prefecture provides excellent conditions for herbs. By carefully nurturing them and bringing out their power, we create fragrant and delicious herbs.
*No pesticides or chemical fertilizers are used. They are cultivated in safe farmland certified by JAS.' where id = 'z7oOM5wuvqVi_ArxRy4C1';
update content_bodies set title = '熊本県南阿蘇村ふるさと納税・返礼品PRムービー「オーガニック野菜のベビーフード」', description = '南阿蘇村返礼品でも人気の離乳食「くちどけ」シリーズ。
栄養士が監修、産婦人科で扱われている安心安全な離乳食です。
はじまりは、有名産婦人科から「離乳食をつくってほしい」という依頼があったことから。
栄養士が監修し、専門医と相談しながらつくったので、どこよりも安心安全です。
現在も有名産婦人科で扱われ、多くの親子に愛されています。

「くちどけシリーズ」を作られている南阿蘇オーガニックはもともと10年以上化粧品やハーブの栽培をしていた会社。もちろんその時からオーガニックにこだわり、安心安全を大切にしてきました。しかし化粧品やハーブにとどまらず、食品の安心安全も追求していくように。特に赤ちゃんに「一番最初から安心安全なものを与えたい」という想いで作られています。


離乳食におすすめ！有機栽培野菜「くちどけシリーズ」
https://www.furusato-tax.jp/product/detail/43433/4646389' where id = 'pt-aRa39zGq6RWLKE0p0J';
update content_bodies set title = 'Kumamoto Prefecture Minami-Aso Village Furusato Tax Donation & Return Gift PR Movie ''Organic Vegetable Baby Food''', description = 'The ''Kuchidoke'' series of baby food is popular among return gifts from Minami-Aso Village.
It is a safe and secure baby food supervised by a nutritionist and used in obstetrics and gynecology.
The beginning was a request from a famous obstetrics and gynecology clinic to ''create baby food.''
Supervised by a nutritionist and developed in consultation with specialists, it is safer and more secure than anywhere else.
It is still used in a well-known obstetrics and gynecology clinic and loved by many parents and children.

Minami-Aso Organic, which produces the ''Kuchidoke series,'' originally had over 10 years of experience in cultivating cosmetics and herbs. 
Of course, they have been committed to organic practices and prioritizing safety and security since then. 
However, they have expanded their pursuit of safety and security in food, not just cosmetics and herbs. 
It is created with the desire to provide babies with ''the safest and most secure products from the very beginning.''

Recommended for baby food! Organic cultivated vegetables ''Kuchidoke series''
https://www.furusato-tax.jp/product/detail/43433/4646389' where id = 'i1z5NQqUTf5bw2ZBixNPa';
update content_bodies set title = '熊本県南阿蘇村ふるさと納税・返礼品PRムービー「南阿蘇の水」編', description = '世界最大級のカルデラを有する阿蘇地域は、阿蘇山の恵み豊かな天然水が湧き出す水源の宝庫。南阿蘇は11箇所の水源をもち、中でも白川水源は毎分60t・ミネラルが適度に含まれた水がこんこんと湧き上がり南阿蘇を代表する水源です。
白川水源をはじめとした各湧水群から湧き出る水は南阿蘇村の田畑を潤し、お米や野菜・果物を美味しく育ててくれます。
「白川水源の水」はミネラルを適度に含んだ中軟水を非加熱処理で美味しさをそのままお届けしています。

南阿蘇村ふるさと納税・返礼品「水」関連商品はコチラから
https://www.furusato-tax.jp/city/product/43433?category_id%5B%5D=112&incsoldout=1' where id = 'm3E5bMcraQOXzUa_zA0Be';
update content_bodies set title = 'Minami Aso Village Furusato Tax and Return Gift PR Movie ''Water of Minami Aso'' Edition', description = 'The Aso region, which has one of the largest calderas in the world, is a treasure trove of natural water sources, blessed with the abundant natural water from Mount Aso. Minami Aso has 11 water sources, among which the Shirakawa Water Source stands out, gushing forth 60 tons of water per minute, rich in minerals, and representing the water sources of Minami Aso.
The water that springs from the various springs, including the Shirakawa Water Source, nourishes the rice fields and farms of Minami Aso Village, allowing delicious rice, vegetables, and fruits to thrive.
The ''Water from Shirakawa Water Source'' is moderately mineralized soft water delivered in its natural taste through non-heating processing.

For Minami Aso Village Furusato Tax and return gift ''water'' related products, click here:
https://www.furusato-tax.jp/city/product/43433?category_id%5B%5D=112&incsoldout=1' where id = 'amrMHFip4lM24YkwgHggF';
update content_bodies set title = '熊本県南阿蘇村ふるさと納税・返礼品PRムービー「南阿蘇菓舗・古今堂」編', description = '生チーズ饅頭一五九二（ひごくに）は素材の選定から向き合った想いのこもった生チーズ饅頭です。チーズ餡の元となる原料は阿部牧場のASOMILK。
2013 国際味覚審査機構にて牛乳では日本で初めての 三ツ星を受賞しました。
そんなＡＳＯＭＩＬＫを使用し自社工場で自家製のクリームチーズを作ることから始め、そのほかの原料にも熊本の地下水で育った小麦を選定しています。独自の製法でしっとりと焼き上げ口の中でとろけるまるで生キャラメルのような不思議な食感を追求しました。また「一五九二（ひごくに）」の由来は熊本県の阿蘇山の標高1592ｍ（高岳）と、肥後の国から名づけられました。冷やしても凍らせても美味しくいただけます。

南阿蘇のお菓子屋『古今堂』一五九二24個入
https://www.furusato-tax.jp/product/detail/43433/5272604' where id = 'zGgeWrny5yjY01OVP2oR3';
update content_bodies set title = 'Kumamoto Prefecture Minami Aso Village Furusato Tax Donation & Return Gift PR Movie ''Minami Aso Confectionery Kikon-do'' Edition', description = 'The fresh cheese bun ''Higokuni'' is a heartfelt creation that has been carefully crafted from the selection of ingredients. The main ingredient for the cheese filling is ASOMILK from Abe Farm.
In 2013, it was awarded the Three Stars at the International Taste Institute, becoming the first in Japan for milk.
Using ASOMILK, we started by making homemade cream cheese in our own factory, and we also select wheat grown with Kumamoto''s underground water for other ingredients. We pursued a unique method to achieve a moist bake with a mysterious texture that melts in your mouth, reminiscent of fresh caramel. Additionally, the name ''Higokuni'' is derived from the elevation of 1592 meters (Takadake) of Mount Aso in Kumamoto Prefecture and is named after the Higo region. It can be enjoyed deliciously whether chilled or frozen.
Minami Aso Confectionery ''Kikon-do'' Higokuni 24 pieces
