update content_bodies set title = '南阿蘇で深呼吸しよ（南阿蘇エリアの4大深呼吸スポット＋αの旅へ）', description = '『空気がうますぎ！元気になれる！南阿蘇エリアの4大深呼吸スポット＋αの旅へ』
https://www.welcomekyushu.jp/article/?mode=detail&id=492

南阿蘇エリアには密を避けた絶景「深呼吸スポット」がたくさんあります。ドライブにピッタリなテイクアウトフードやカフェ、そしていちご狩りやパワースポットなどのアクティビティもあって、1日中楽しめること間違いなし。
暖かな陽気とともに、息抜きをしにぐるり南阿蘇へ春のお出かけはいかがですか？

↓お出かけドライブのモデルコースはコチラ↓

『空気がうますぎ！元気になれる！南阿蘇エリアの4大深呼吸スポット＋αの旅へ』
https://www.welcomekyushu.jp/article/?mode=detail&id=492

