update content_bodies set title = '津軽あかつきの会「故郷の味を100年先まで」', description = '青森県弘前市で、津軽地方の郷土料理と食文化を伝える「伝承料理」活動をしている女性だけの料理研究ユニット、「津軽あかつきの会」のオリジナルショートムービーです。（※2021年に撮影）
 
 
