update content_bodies set title = '“まるで海外”な青森の絶景スポットを紹介！「ここも青森」CM', description = '青森には、ハワイやカッパドキア、北欧などを連想させる絶景スポットがあります。
新型コロナウイルスの影響でなかなか海外旅行に行けない状況ですが、
ちょっと海外気分を味わえる青森のスポットをぜひご覧ください！
もちろん海外にはない、青森ならではの魅力も満載です。

